+
+    for (i, test) in tests.into_iter().enumerate() {
+        if !filter.is_empty() && !test.used_methods.iter().any(|m| m.starts_with(&filter)) {
+            filtered += 1;
+            continue;
+        }
+
+        print!(
+            "test {} ... ",
