+async fn get_logs_for_tx(
+    client: &rpc::Client,
+    spec: EthFilterSpec,
+    tx_hash: &EthHash,
+) -> anyhow::Result<Vec<EthLogView>> {
+    let result = client.call(EthGetLogs::request((spec,))?).await?;
+    let mut logs: Vec<EthLogView> = logs_from_result(result)?
+        .into_iter()
+        .filter(|log| &log.transaction_hash == tx_hash)
+        .collect();
+    logs.sort_by_key(|log| log.log_index.0);
+    Ok(logs)
+}
+
+/// Drain a `logs` subscription, collecting the logs produced by `tx`.
+async fn collect_subscription_logs(
+    ws: &mut EthSubStream,
+    subscription_id: &serde_json::Value,
+    tx_hash: &EthHash,
+    want: usize,
+    budget: Duration,
+) -> anyhow::Result<Vec<EthLogView>> {
+    let deadline = std::time::Instant::now() + budget;
+    let mut logs = Vec::new();
+    let mut seen = BTreeSet::new();
+    while seen.len() < want {
+        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
+        if remaining.is_zero() {
+            break;
+        }
+        match next_subscription_payload(ws, subscription_id, remaining).await {
+            Ok(payload) => {
+                ensure!(
+                    payload.is_object(),
+                    "a logs notification must be a single log object, got: {payload}"
+                );
+                let log: EthLogView =
+                    serde_json::from_value(payload).context("subscription log payload")?;
+                if &log.transaction_hash == tx_hash && seen.insert(log.log_index.0) {
+                    logs.push(log);
+                }
+            }
+            // Timed out waiting for the next notification (or the stream ended): done draining.
+            Err(_) => break,
+        }
+    }
+    Ok(logs)
+}
