+        // ALICE's part: 40 * 75/100 = 30 before, 80 * 75/100 = 60 after.
+        // BOB's part: 40 * 25/100 = 10 before, 80 * 25/100 = 20 after.
+        assert_eq!(earned(&stream_rewards, SERVICE_STREAM), [30, 10]); // 60 - 30, 20 - 10
