+    /// A call the reward actor made while it ran the award, sending `value` to `to`.
+    fn transfer(to: Address, value: i64, exit_code: u32) -> ExecutionTrace {
+        ExecutionTrace {
+            msg: MessageTrace {
+                from: Address::REWARD_ACTOR,
